  const seqs = (evidence ?? []).map((ref) => ref?.coordinationSeq).filter(Number.isInteger);
  const seq = seqs.length > 0 ? Math.min(...seqs) : fallback.seq;
  return { eventTimeSeq: seq, eventTime: events[seq - 1]?.ts ?? fallback.ts };
