      this._knowledgeNodes.set(p.nodeId, freeze({ ...clone(target), validTo: p.validTo ?? event.ts, validityVersion: target.validityVersion + 1, invalidatedBy: event.seq }));
    } else if (event.kind === 'knowledge.read') {
